<!doctype html>
<html lang="da">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Opret server · Nodexa</title>
<style>
:root{color-scheme:dark;--bg:#080a0f;--panel:#11151e;--panel2:#0d1118;--line:#252c3a;--text:#f3f5fa;--muted:#929cad;--purple:#765cff;--purple2:#986cff;--green:#43d6a2;--red:#fb7185;--yellow:#fbbf24}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% -10%,rgba(117,92,255,.18),transparent 32%),var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{min-height:100vh}.top{height:70px;border-bottom:1px solid var(--line);background:rgba(8,10,15,.9);display:flex;align-items:center;justify-content:space-between;padding:0 max(20px,calc((100vw - 1180px)/2));position:sticky;top:0;z-index:20;backdrop-filter:blur(18px)}.brand{display:flex;align-items:center;gap:10px;font-weight:900;letter-spacing:.09em}.mark{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:linear-gradient(135deg,var(--purple),var(--purple2));box-shadow:0 10px 30px rgba(118,92,255,.25)}.top a{color:#aeb6c5;text-decoration:none}.top a:hover{color:white}.wrap{width:min(1180px,calc(100% - 30px));margin:34px auto 80px}.crumb{font-size:11px;color:#777f90;text-transform:uppercase;letter-spacing:.12em}.heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;margin:9px 0 25px}.heading h1{font-size:34px;margin:0 0 6px}.heading p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px}.stack{display:grid;gap:18px}.card{border:1px solid var(--line);background:linear-gradient(180deg,#111620,#0d1119);border-radius:15px;padding:22px;box-shadow:0 20px 70px rgba(0,0,0,.16)}.card h2{font-size:17px;margin:0 0 5px}.card>p{color:var(--muted);margin:0 0 21px;line-height:1.55;font-size:12px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field.wide{grid-column:1/-1}.field label{display:block;color:#aeb6c5;font-size:11px;font-weight:800;margin:0 0 7px}.field input,.field select,.field textarea{width:100%;border:1px solid #293243;background:#090d14;color:white;border-radius:9px;padding:11px 12px;outline:none;font:inherit}.field textarea{min-height:105px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.field input:focus,.field select:focus,.field textarea:focus{border-color:#7662df;box-shadow:0 0 0 3px rgba(118,98,223,.12)}.hint{display:block;color:#747e90;font-size:10px;margin-top:6px;line-height:1.45}.resources{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.summary{position:sticky;top:90px;height:max-content}.summaryBox{display:grid;gap:0;margin-top:15px}.sum{display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid var(--line);color:#a5afbf}.sum strong{color:#e9edf5;text-align:right}.node-state{display:flex;align-items:center;gap:8px}.dot{width:8px;height:8px;border-radius:50%;background:#596172}.dot.ok{background:var(--green)}.btn{border:1px solid var(--line);background:#151a24;color:white;border-radius:10px;padding:11px 15px;font-weight:850;cursor:pointer}.btn.primary{width:100%;border:0;background:linear-gradient(135deg,var(--purple),var(--purple2));box-shadow:0 12px 35px rgba(118,92,255,.23);margin-top:18px}.btn:disabled{opacity:.5;cursor:not-allowed}.msg{display:none;border-radius:10px;padding:12px 14px;margin:0 0 18px;white-space:pre-wrap;line-height:1.5}.msg.show{display:block}.msg.error{background:#27131a;border:1px solid #643042;color:#ffb1c0}.msg.warn{background:#261e0c;border:1px solid #67511b;color:#ffd978}.msg.ok{background:#0e251d;border:1px solid #285f4b;color:#92efca}.presetbar{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 18px}.preset{padding:8px 11px;border-radius:999px;border:1px solid #2b3342;background:#10151e;color:#aeb7c6;font-size:11px;cursor:pointer}.preset.active{border-color:#6656c4;background:#211c3b;color:#d8d0ff}.empty{padding:18px;border:1px dashed #3a4250;border-radius:11px;color:#aab2c0;line-height:1.5}.successBox{display:none}.successBox.show{display:block}.successId{font-size:28px;font-weight:900;margin:4px 0}.links{display:flex;gap:8px;margin-top:16px}.links a{flex:1;text-align:center;text-decoration:none}.dangerText{color:#fb98aa}.mini{font-size:10px;color:#737d8e;margin-top:12px}@media(max-width:850px){.grid{grid-template-columns:1fr}.summary{position:static}.heading{align-items:flex-start;flex-direction:column}.fields,.resources{grid-template-columns:1fr}.field.wide{grid-column:auto}.wrap{margin-top:24px}}
</style>
</head>
<body>
<div class="shell">
<header class="top"><div class="brand"><span class="mark">N</span><span>NOD<span style="color:#9278ff">EXA</span></span></div><a href="/">← Tilbage til kontrolpanel</a></header>
<main class="wrap">
<div class="crumb">ADMINISTRATION · SERVERE · OPRET</div>
<div class="heading"><div><h1>Opret server</h1><p>Provisionér en ny game server på en af dine Nodexa Nodes.</p></div></div>
<div id="message" class="msg"></div>
<div class="grid">
<form id="form" class="stack">
<section class="card"><h2>Grundlæggende oplysninger</h2><p>Vælg ejer, navn og den Node serveren skal placeres på.</p><div class="fields">
<div class="field wide"><label>Servernavn</label><input id="name" maxlength="120" required placeholder="Zematic RP FiveM"></div>
<div class="field"><label>Ejer</label><select id="owner" required><option value="">Indlæser brugere…</option></select><span class="hint">Kun eksisterende Nodexa-konti kan være serverejer.</span></div>
<div class="field"><label>Node</label><select id="node" required><option value="">Indlæser Nodes…</option></select><span class="hint">Serveren oprettes fysisk på den valgte Nodexa Agent.</span></div>
</div></section>
<section class="card"><h2>Runtime & startup</h2><p>Docker-image og startup-kommando svarer til Pterodactyls Startup-konfiguration.</p><div class="presetbar"><button type="button" class="preset active" data-preset="custom">Custom</button><button type="button" class="preset" data-preset="minecraft">Minecraft Java</button><button type="button" class="preset" data-preset="fivem">FiveM</button></div><div class="fields">
<div class="field wide"><label>Docker Image</label><input id="image" required value="ghcr.io/parkervcp/yolks:debian" placeholder="ghcr.io/...:tag"></div>
<div class="field wide"><label>Startup Command</label><textarea id="startup" required placeholder="Kommando der starter serveren"></textarea><span class="hint">Dette styrer kun opstarten. Game-filer/install scripts håndteres senere af Templates/Eggs-modulet.</span></div>
<div class="field wide"><label>Environment variables</label><textarea id="environment" placeholder="SERVER_PORT=30120&#10;MAX_PLAYERS=48"></textarea><span class="hint">Én KEY=VALUE pr. linje. Hemmeligheder bør ikke indsættes her, hvis de ikke behøver at være startup-variabler.</span></div>
</div></section>
<section class="card"><h2>Ressourcer</h2><p>Fastlæg de maksimale ressourcer, containeren må bruge.</p><div class="resources">
<div class="field"><label>RAM (MB)</label><input id="memory" type="number" min="128" value="4096" required></div>
<div class="field"><label>Disk (MB)</label><input id="disk" type="number" min="512" value="20000" required></div>
<div class="field"><label>CPU Limit (%)</label><input id="cpu" type="number" min="0" max="1000" value="100" required><span class="hint">100 = ca. 1 CPU core, 200 = ca. 2 cores.</span></div>
</div></section>
</form>
<aside class="card summary"><h2>Provisionering</h2><p>Nodexa opretter server-ID, container og tildeler ejeren automatisk.</p><div class="summaryBox"><div class="sum"><span>Status</span><strong class="node-state"><i id="statusDot" class="dot"></i><span id="statusText">Klar</span></strong></div><div class="sum"><span>Server ID</span><strong>Automatisk s#</strong></div><div class="sum"><span>Node</span><strong id="sumNode">Ikke valgt</strong></div><div class="sum"><span>Ejer</span><strong id="sumOwner">Ikke valgt</strong></div><div class="sum"><span>RAM</span><strong id="sumRam">4 GB</strong></div><div class="sum"><span>Disk</span><strong id="sumDisk">19.5 GB</strong></div><div class="sum"><span>CPU</span><strong id="sumCpu">100%</strong></div></div><button id="submit" class="btn primary" type="button">Opret & provisionér server</button><div class="mini">Hvis Agenten ikke kan kontaktes, bliver serveren markeret <span class="dangerText">install_failed</span> og den konkrete Node-fejl vises under Admin → Fejl.</div><div id="success" class="successBox"><div class="mini">SERVER OPRETTET</div><div id="successId" class="successId">s#</div><div id="successName"></div><div class="links"><a class="btn" href="/">Åbn panel</a><a class="btn" href="/admin/errors">Se fejl</a></div></div></aside>
</div>
</main></div>
<script>
const TOKEN=localStorage.getItem('nodexa_panel_token');
const headers={Authorization:'Bearer '+TOKEN,Accept:'application/json','Content-Type':'application/json'};
const $=id=>document.getElementById(id);
const msg=(text,type='error')=>{const e=$('message');e.className='msg show '+type;e.textContent=text;window.scrollTo({top:0,behavior:'smooth'})};
const json=async(r)=>{let d={};try{d=await r.json()}catch{}return d};
const prettyError=d=>{if(d?.errors){return Object.entries(d.errors).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(' '):v}`).join('\n')}return d?.message||d?.error||'Ukendt fejl.'};
function formatMb(v){v=Number(v)||0;return v>=1024?`${(v/1024).toFixed(v%1024===0?0:1)} GB`:`${v} MB`}
function parseEnvironment(){const out={};$('environment').value.split(/\r?\n/).forEach(line=>{line=line.trim();if(!line||line.startsWith('#'))return;const i=line.indexOf('=');if(i<1)return;out[line.slice(0,i).trim()]=line.slice(i+1)});return out}
function updateSummary(){const n=$('node').selectedOptions[0];const o=$('owner').selectedOptions[0];$('sumNode').textContent=n&&n.value?n.textContent:'Ikke valgt';$('sumOwner').textContent=o&&o.value?o.textContent:'Ikke valgt';$('sumRam').textContent=formatMb($('memory').value);$('sumDisk').textContent=formatMb($('disk').value);$('sumCpu').textContent=($('cpu').value||0)+'%'}
async function boot(){if(!TOKEN){location.href='/';return}const me=await fetch('/api/me',{headers}).then(async r=>r.ok?json(r):null).catch(()=>null);if(!me?.is_admin){location.href='/';return}
 const [nodesR,usersR]=await Promise.all([fetch('/api/nodes',{headers}),fetch('/api/admin/users',{headers})]);const nodesD=await json(nodesR),usersD=await json(usersR);const nodes=Array.isArray(nodesD)?nodesD:(nodesD.data||[]);const users=Array.isArray(usersD)?usersD:(usersD.data||[]);
 $('node').innerHTML=nodes.length?'<option value="">Vælg Node…</option>'+nodes.map(n=>`<option value="${n.id}">${escapeHtml(n.name)} · ${escapeHtml(n.fqdn)} · ${n.servers_count||0} servere</option>`).join(''):'<option value="">Ingen Nodes oprettet</option>';
 $('owner').innerHTML=users.length?users.map(u=>`<option value="${u.id}" ${u.id===me.id?'selected':''}>${escapeHtml(u.name||u.email)} · ${escapeHtml(u.email)}</option>`).join(''):'<option value="">Ingen brugere fundet</option>';
 if(!nodes.length)msg('Der er ingen Nodes. Opret og konfigurer først en Node under Admin → Node Setup.','warn');updateSummary()}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
const presets={custom:{image:'ghcr.io/parkervcp/yolks:debian',startup:''},minecraft:{image:'ghcr.io/parkervcp/yolks:java_21',startup:'java -Xms128M -XX:MaxRAMPercentage=95.0 -jar server.jar'},fivem:{image:'ghcr.io/parkervcp/yolks:debian',startup:'bash ./run.sh'}};
document.querySelectorAll('.preset').forEach(b=>b.onclick=()=>{document.querySelectorAll('.preset').forEach(x=>x.classList.remove('active'));b.classList.add('active');const p=presets[b.dataset.preset];$('image').value=p.image;$('startup').value=p.startup});
['node','owner','memory','disk','cpu'].forEach(id=>$(id).addEventListener('input',updateSummary));
$('submit').onclick=async()=>{const required=[$('name'),$('owner'),$('node'),$('image'),$('startup'),$('memory'),$('disk'),$('cpu')];if(required.some(e=>!String(e.value).trim())){msg('Udfyld alle obligatoriske felter.');return}const btn=$('submit');btn.disabled=true;btn.textContent='Provisionerer…';$('statusDot').classList.add('ok');$('statusText').textContent='Provisionerer';
 const payload={name:$('name').value.trim(),owner_id:Number($('owner').value),node_id:Number($('node').value),docker_image:$('image').value.trim(),startup:$('startup').value.trim(),memory_mb:Number($('memory').value),disk_mb:Number($('disk').value),cpu_limit:Number($('cpu').value),environment:parseEnvironment()};
 try{const r=await fetch('/api/servers',{method:'POST',headers,body:JSON.stringify(payload)});const d=await json(r);if(!r.ok){if(d?.server){$('success').classList.add('show');$('successId').textContent=d.server.identifier||'Oprettet';$('successName').textContent=d.server.name||payload.name;msg(`${d.message||'Server oprettet, men provisionering fejlede.'}\n\n${d.error||''}\n\nSe Admin → Fejl for Node-diagnosen.`,'warn')}else msg(prettyError(d));return}
 $('success').classList.add('show');$('successId').textContent=d.identifier||'Server';$('successName').textContent=d.name||payload.name;$('statusText').textContent='Oprettet';msg(`Server ${d.identifier||''} blev oprettet og provisioneret på noden.`,'ok')
 }catch(e){msg('Kunne ikke kontakte Nodexa API: '+(e?.message||e))}finally{btn.disabled=false;btn.textContent='Opret & provisionér server'}};
boot().catch(e=>msg('Server Setup kunne ikke indlæses: '+(e?.message||e)));
</script>
</body>
</html>
